async function loadGoogleFont(family: string, weight: number, text: string) {
  const css = await (
    await fetch(
      `https://fonts.googleapis.com/css2?family=${family}:wght@${weight}&text=${encodeURIComponent(text)}`,
    )
  ).text();
  const match = css.match(/src: url\(([^)]+)\) format\('(opentype|truetype)'\)/);
  if (match) {
    const res = await fetch(match[1]);
    if (res.ok) return res.arrayBuffer();
  }
  throw new Error(`Failed to load font: ${family}`);
}

/**
 * Social share card. Replaces the old static "Stay Tuned" placeholder image
 * with one that carries the site's actual positioning: the multiplayer
 * tagline, the private beta status, the real wordmark. Generated at request
 * time via next/og instead of a static PNG so copy changes here never drift
 * from what the site actually says.
 */
